local PolisherMaker = {}
local PRODUCTS = {
    simple_wood_polisher = { name = "Preprost leseni polirnik", woodCost = 4, leatherCost = 2, waxCost = 1, time = 4, cost = 150, science = 18, happiness = 1, description = "Preprost leseni polirnik za poliranje." },
    iron_reinforced_polisher = { name = "Železnookrepljen polirnik", woodCost = 3, ironCost = 2, leatherCost = 2, waxCost = 1, time = 7, cost = 380, science = 28, happiness = 2, prestige = 2, description = "Železnookrepljen polirnik za trgovce." },
    silver_drum_polisher = { name = "Srebrnobobenski polirnik", woodCost = 3, ironCost = 2, silverCost = 1, leatherCost = 2, waxCost = 1, time = 11, cost = 880, science = 42, happiness = 2, prestige = 6, description = "Srebrnobobenski polirnik za plemiče." },
    gold_trimmed_polisher = { name = "Zlatookrasni polirnik", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, leatherCost = 2, waxCost = 1, time = 15, cost = 2000, science = 56, happiness = 3, prestige = 14, description = "Zlatookrasni polirnik za visoke plemiče." },
    jewel_set_polisher = { name = "Draguljasta polirnik", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, leatherCost = 2, waxCost = 1, jewelCost = 1, time = 19, cost = 4400, science = 72, happiness = 5, prestige = 27, description = "Polirnik z draguljem za visoko plemstvo." },
    royal_grand_polisher = { name = "Kraljevski veliki polirnik", woodCost = 5, ironCost = 3, goldCost = 2, silverCost = 2, leatherCost = 2, waxCost = 1, jewelCost = 2, pearlCost = 2, time = 26, cost = 9500, science = 90, happiness = 12, prestige = 58, description = "Veliki kraljevski polirnik z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    polisher_workshop = { name = "Polirniška delavnica", cost = { gold = 280, wood = 160, stone = 120, leather = 6, wax = 6 }, upkeep = 6, qualityBonus = 5 },
    machinery_loft = { name = "Strojna podstrešje", cost = { gold = 1000, wood = 320, stone = 280, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_machinist_atelier = { name = "Mojstrski strojniški atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_machinery_palace = { name = "Kraljevska strojna palača", cost = { gold = 11500, wood = 600, stone = 800, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
PolisherMaker.woodStock = 20; PolisherMaker.ironStock = 12; PolisherMaker.leatherStock = 14; PolisherMaker.waxStock = 10; PolisherMaker.silverStock = 6; PolisherMaker.goldStock = 6; PolisherMaker.jewelStock = 4; PolisherMaker.pearlStock = 4
PolisherMaker.productStock = {}; PolisherMaker.buildings = {}; PolisherMaker.maker = nil; PolisherMaker.activeMaking = {}; PolisherMaker.totalProducts = 0; PolisherMaker.dayTimer = 0
function PolisherMaker.init() PolisherMaker.woodStock=20; PolisherMaker.ironStock=12; PolisherMaker.leatherStock=14; PolisherMaker.waxStock=10; PolisherMaker.silverStock=6; PolisherMaker.goldStock=6; PolisherMaker.jewelStock=4; PolisherMaker.pearlStock=4; PolisherMaker.productStock={}; PolisherMaker.buildings={}; PolisherMaker.maker=nil; PolisherMaker.activeMaking={}; PolisherMaker.totalProducts=0; PolisherMaker.dayTimer=0; print("[PolisherMaker] Royal Polisher Maker System initialized (6 products, 4 buildings)") end
function PolisherMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PolisherMaker.maker={name=n or ("Polirnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polirnikar najet: %s (spretnost: %d)",PolisherMaker.maker.name,s),"success") end; return true end
function PolisherMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PolisherMaker.build(id) local ok,e=PolisherMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PolisherMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PolisherMaker.getQualityBonus() local b=0; for _,bd in ipairs(PolisherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PolisherMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and PolisherMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and PolisherMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.leatherCost and PolisherMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.waxCost and PolisherMaker.waxStock<(d.waxCost or 0) then return false,"Premalo voska" end; if d.silverCost and PolisherMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PolisherMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PolisherMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PolisherMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PolisherMaker.buildings==0 then return false,"Potrebna polirniška delavnica" end; if not PolisherMaker.maker then return false,"Potreben polirnikar" end; return true end
function PolisherMaker.make(pt,qty) qty=qty or 1; local ok,e=PolisherMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then PolisherMaker.woodStock=PolisherMaker.woodStock-d.woodCost*qty end; if d.ironCost then PolisherMaker.ironStock=PolisherMaker.ironStock-d.ironCost*qty end; if d.leatherCost then PolisherMaker.leatherStock=PolisherMaker.leatherStock-d.leatherCost*qty end; if d.waxCost then PolisherMaker.waxStock=PolisherMaker.waxStock-d.waxCost*qty end; if d.silverCost then PolisherMaker.silverStock=PolisherMaker.silverStock-d.silverCost*qty end; if d.goldCost then PolisherMaker.goldStock=PolisherMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PolisherMaker.jewelStock=PolisherMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PolisherMaker.pearlStock=PolisherMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PolisherMaker.maker then t=math.max(1,t-math.floor(PolisherMaker.maker.skill/13)) end; table.insert(PolisherMaker.activeMaking,{id="polisher_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PolisherMaker.completeMaking(m) local q=1.0+(PolisherMaker.getQualityBonus()/100); if PolisherMaker.maker then q=q+(PolisherMaker.maker.skill/140) end; q=math.min(2.5,q); PolisherMaker.productStock[m.productType]=(PolisherMaker.productStock[m.productType] or 0)+m.quantity; PolisherMaker.totalProducts=PolisherMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PolisherMaker.maker then PolisherMaker.maker.itemsMade=PolisherMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PolisherMaker.maker.skill=math.min(100,PolisherMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polirnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"polisher.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function PolisherMaker.update(dt) if not _G.state then return end; PolisherMaker.dayTimer=PolisherMaker.dayTimer+dt; if PolisherMaker.dayTimer>=30 then PolisherMaker.dayTimer=0; for i=#PolisherMaker.activeMaking,1,-1 do local m=PolisherMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PolisherMaker.completeMaking(m); table.remove(PolisherMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PolisherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PolisherMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PolisherMaker.getStats() return {woodStock=PolisherMaker.woodStock,ironStock=PolisherMaker.ironStock,leatherStock=PolisherMaker.leatherStock,waxStock=PolisherMaker.waxStock,silverStock=PolisherMaker.silverStock,goldStock=PolisherMaker.goldStock,jewelStock=PolisherMaker.jewelStock,pearlStock=PolisherMaker.pearlStock,productStock=PolisherMaker.productStock,numBuildings=#PolisherMaker.buildings,hasMaker=PolisherMaker.maker~=nil,makerName=PolisherMaker.maker and PolisherMaker.maker.name or "—",makerSkill=PolisherMaker.maker and PolisherMaker.maker.skill or 0,activeMaking=#PolisherMaker.activeMaking,totalProducts=PolisherMaker.totalProducts} end
return PolisherMaker
